const GLOSSARY = [
  ['pH', 'A 0–14 scale of acidity. Healthy skin sits around 4.5–5.5 (slightly acidic) — that\'s why harsh soaps (pH 9–10) can feel tight.'],
  ['Comedogenic', 'Likely to clog pores and cause comedones (blackheads/whiteheads). "Non-comedogenic" products are formulated to avoid this, though it is not a regulated claim.'],
  ['Comedone', 'A clogged pore — open (blackhead) or closed (whitehead).'],
  ['SPF', 'Sun Protection Factor — how well a sunscreen protects from UVB rays that cause burning.'],
  ['PA++++', 'Protection Grade of UVA, used in Asia. More pluses = more protection from tanning and aging UVA rays. PA++++ is the highest.'],
  ['Broad spectrum', 'Protection against both UVA and UVB.'],
  ['UV Index', 'A 0–11+ scale of the sun\'s UV strength. 3+ needs sunscreen; 8+ is very high (common across India).'],
  ['AHA', 'Alpha hydroxy acids (glycolic, lactic, mandelic) — water-soluble surface exfoliants.'],
  ['BHA', 'Beta hydroxy acid (salicylic) — oil-soluble exfoliant that gets inside pores.'],
  ['PHA', 'Poly hydroxy acids (gluconolactone) — the gentlest exfoliating acids.'],
  ['Retinoid', 'The vitamin A family: retinol, retinal, adapalene, tretinoin. Boost cell turnover and collagen.'],
  ['Humectant', 'Ingredient that attracts water (glycerin, hyaluronic acid).'],
  ['Emollient', 'Ingredient that softens and smooths (squalane, plant oils).'],
  ['Occlusive', 'Forms a seal to stop water loss (petrolatum, dimethicone).'],
  ['TEWL', 'Trans-epidermal water loss — water escaping through the skin. High TEWL = weak barrier.'],
  ['Skin barrier', 'The outer layer (stratum corneum) of cells + lipids that keeps water in and irritants out.'],
  ['Purging', 'Temporary breakouts when starting actives that speed cell turnover. Should settle in 4–6 weeks, in your usual breakout areas.'],
  ['PIH', 'Post-inflammatory hyperpigmentation — brown/dark marks left after acne or injury. Common in Indian skin.'],
  ['PIE', 'Post-inflammatory erythema — red/pink marks after acne.'],
  ['Melasma', 'Symmetrical brown patches triggered by hormones, UV, heat and visible light.'],
  ['Sebum', 'The oil your skin glands make.'],
  ['Fitzpatrick scale', 'Classifies skin (I–VI) by how it reacts to sun. Most Indian skin is III–V.'],
  ['Patch test', 'Trying a product on a small area for a few days to check for reactions.'],
  ['Double cleansing', 'Oil cleanser followed by a water-based cleanser to remove sunscreen and makeup.'],
  ['Hair porosity', 'How easily hair absorbs and holds moisture. High porosity = absorbs fast, loses fast (often damaged hair).'],
  ['Keratin', 'The protein hair is made of.'],
  ['Telogen effluvium', 'Temporary, diffuse shedding 2–3 months after stress, illness or childbirth.'],
  ['Malassezia', 'A yeast naturally on skin; overgrowth causes dandruff and fungal acne.'],
  ['Sulfate-free', 'Shampoos without SLS/SLES — gentler cleansing, less stripping.'],
  ['Fragrance-free', 'No added fragrance (different from "unscented", which may contain masking fragrance).'],
];

